    "description": "美东时间周一盘后，苹果CEO约翰・特努斯在财报会上表示，内存价格上涨正拖累公司新一季度毛利率环比下滑。他表示：“我们目前看到的内存定价是前所未有的。正如我们在9月财季（第四财季）早些时候所说，与6月财季（第三财季）相比，我们确实看到了更高的内存成本，其中部分被库存递延收益和某些非内存组件成本下降所抵消。对于12月财季（2027财年第一财季），我们预计内存成本会更高。”（财联社）",
    "content": "美东时间周一盘后，苹果CEO约翰・特努斯在财报会上表示，内存价格上涨正拖累公司新一季度毛利率环比下滑。他表示：“我们目前看到的内存定价是前所未有的。正如我们在9月财季（第四财季）早些时候所说，与6月财季（第三财季）相比，我们确实看到了更高的内存成本，其中部分被库存递延收益和某些非内存组件成本下降所抵消。对于12月财季（2027财年第一财季），我们预计内存成本会更高。”（财联社）"
