    "description": "用了几年 gpt 。基本都是工作中开发代码, pro 用不完, plus 不够用（有段时间双持）。 1. 感觉 gpt 不断降智, 6 不够用, 6.1sol 需要改几次。 2. 额度不断降低, gpt 和 codex 的额度还要合并 3. plus5 小时额度卡着很难受。重置和重置卡对 plus 用户意义很小。 也需等更新了新模型会好点, 但新模型肯定也是消耗巨大。 订阅了 Grok, 主要是玩 bot, 还没用来开发 Claude …",
    "content": "用了几年 gpt 。基本都是工作中开发代码, pro 用不完, plus 不够用（有段时间双持）。 1. 感觉 gpt 不断降智, 6 不够用, 6.1sol 需要改几次。 2. 额度不断降低, gpt 和 codex 的额度还要合并 3. plus5 小时额度卡着很难受。重置和重置卡对 plus 用户意义很小。 也需等更新了新模型会好点, 但新模型肯定也是消耗巨大。 订阅了 Grok, 主要是玩 bot, 还没用来开发 Claude Code 封号严重, 没实力高成本订阅。 问问大家有啥想法？没有更好的方案？"
