    "pub_date": "2026-11-03 11:09:31",
    "author": "",
    "description": "据未具名韩国官员称，在金融业近期遭遇网络攻击后，韩国国家情报院要求约2100家中央和地方政府机构开展紧急安全检查。韩国国家情报院10月22日要求这些机构按照检查清单开展自查，重点检查面向外部的系统、安全监控以及是否安装了安全补丁该机构还在另行检查公共部门关键IT基础设施是否存在安全漏洞，相关检查将于11月中旬前完成。韩国科技信息通信部自10月下旬以来也一直在对111家机构开展安全漏洞检查。这些机构负责管理约170处民营部门关键信息通信基…",
    "content": "据未具名韩国官员称，在金融业近期遭遇网络攻击后，韩国国家情报院要求约2100家中央和地方政府机构开展紧急安全检查。韩国国家情报院10月22日要求这些机构按照检查清单开展自查，重点检查面向外部的系统、安全监控以及是否安装了安全补丁该机构还在另行检查公共部门关键IT基础设施是否存在安全漏洞，相关检查将于11月中旬前完成。韩国科技信息通信部自10月下旬以来也一直在对111家机构开展安全漏洞检查。这些机构负责管理约170处民营部门关键信息通信基础设施。"
