    "author": "gooddeveloper",
    "description": "1.作为北方人，前年去过一次成都爱上了吃川渝火锅和油碟，并且这两年吃火锅再也不吃任何羊肉卷、牛肉卷了，只吃吊龙、匙柄等肉(看了网上的潮汕牛肉，非常带劲)，想的也是多吃牛肉应该不像猪肉那样长胖，麻酱碟也不吃了，最近吃过比较好吃的油碟锅是在海底捞的大排档，体感挺好～ 2.近来复刻准备： (1)周大签锅底，B 站刷到了好多次准备买一次试试，单价还挺贵，不过想复刻锅底应该是关键，有没有小伙伴推荐性价比更高的？ (2)香油，也是顺带买的周大签的，…",
