    "content": "国家发展改革委召开奋进“十五五”系列新闻发布会，介绍培育壮大新动能有关情况。国家发展改革委创新和高技术发展司副司长任中保在回答记者提问时表示，未来产业培育周期长，市场风险高，需要政府在加大投入的同时健全风��分担机制，我们将充分发挥国家创业投资引导基金示范作用，将未来产业种子期、初创期、早中期的企业作为投资重点，用耐心资本陪伴企业产业创新，带动社会资本投早投小投长期投硬科技。同时我们将配合有关方面加大融资担保、风险补偿等政策支持力度，开发科技保险等专属产品，更好保障未来企业发展。（证券时报）"
