    "content": "翻译｜林绮蓓 编辑｜蔡芳芳 谷歌有多少代码是AI写的？去年，CEO 桑达尔·皮查伊（Sundar Pichai）还给出过一个明确的数字：25%。但当主持人再次问起这个问题时，他的回答却改变了：“这个比例已经没有太大意义。” 因为 AI 已经深度参与谷歌内部的代码开发。Gemini 4 Argon 发布后的四周内，谷歌代码变更提交量增加约 30%，回滚次数减少约三分之一，开发人员开始用 Gemini 4 Argon 处理涉及数百万行代码的复杂项目。相比 AI 编写代码的比例，谷歌现在更关注代码变更量、回滚情况等指标。…"
