    "content": "近期，“欠缴社保最高罚3倍”的言论被网民热议，把社保这个老话题顶上了热搜。 评论区里，各种声音都不少。有的算账：“3000块的工资，扣完社保还剩多少？”“公司按最低基数缴，跟足额缴的比，退休金能差出一大截”“灵活就业的没单位分担，20%的缴费全自己扛”…… 有的担忧：“是不是社保要见底了”“小企业难开了，大公司外包出去的更多了”。也有人认为：“多缴才能多得”“企业要习惯抬高成本”。 讨论之际，恰逢一部新规落地。11月1日起施行的《全国税务行政处罚裁量基准（2026年版）》，首次将社保欠缴处罚纳入全国统一的裁量体系。…"
