    "description": "记者3日从四川成都举行的2026全球熊猫伙伴大会上获悉，截至目前，我国大熊猫圈养种群达830只，种群遗传多样性持续提升。近年来，通过开展生态廊道建设，13个大熊猫局域种群回归大家庭，生境连通性显著提升，廊道区域监测到150余次大熊猫及其他物种活动，大熊猫“串门”“相亲”成为常态。大熊猫是我国特有旗舰物种，也是世界生物多样性保护的明星物种。据统计，全球观赏大熊猫游客总数累计超过10亿人次。",
