    "category": "新闻",
    "title": "检察机关依法对郭学益涉嫌受贿、行贿、贪污案提起公诉",
    "link": "http://www.news.cn/20261103/9ce819e5349d476bad0c89d967e88099/c.html",
    "pub_date": "2026-11-03 10:00:58",
    "author": "",
    "description": "新华社北京11月3日电 记者11月3日从最高人民检察院获悉，中南大学原党委常委、副校长郭学益涉嫌受贿、行贿、贪污一案，由国家监察委员会调查终结，移送检察机关审查起诉。经最高人民检察院指定管辖，安徽省人民检察院依法以涉嫌受贿罪、行贿罪、贪污罪对郭学益作出逮捕决定。近日，安徽省六安市人民检察院已向六安市中级人民法院提起公诉。 检察机关在审查起诉阶段，依法告知了被告人郭学益享有的诉讼权利，并讯问了被告人，听取了辩护人的意见。检察机关起诉指控：…",
