    "content": "新华社北京11月3日电（记者吴雨）记者11月3日从中国人民银行获悉，为加强金融机构外汇流动性管理，中国人民银行决定，自2026年11月15日起，上调金融机构外汇存款准备金率2个百分点，即外汇存款准备金率由现行的4%提高到6%。"
